    [Fact]
    public void MultipleReturnsDifferentTypes_ThrowsError()
    {
        // Arrange
        var blakeSource = @"namespace MyApp;

public class Test
{
    public var GetValue(bool useString)
    {
        if (useString)
            return ""text"";
        return 42;
    }
}
";

        // Act & Assert
        var parser = new BlakeParser(blakeSource, "test.blake");
        var ast = parser.Parse();

        var interpreter = new BlakeInterpreter("test.blake");

        var exception = Assert.Throws<BlakeExecutionException>(() => interpreter.Expand(ast));
        Assert.Contains("conflicting types", exception.Message);
        Assert.Contains("string", exception.Message);
        Assert.Contains("int", exception.Message);
    }

