    [Fact]
    public void TransformationIsActuallyRun_DebugTest()
    {
        // This test verifies that our transformation pipeline is actually being called
        var blakeSource = @"namespace MyApp;

public class Test
{
    public var GetValue() => 42;
}
";

        var parser = new BlakeParser(blakeSource, "test.blake");
        var ast = parser.Parse();

        var interpreter = new BlakeInterpreter("test.blake");
        var output = interpreter.Expand(ast);

        // The output should NOT contain "var" as a return type
        Assert.DoesNotContain("public var GetValue", output);
        // It SHOULD contain the inferred type
        Assert.Contains("public int GetValue", output);
    }
